<script setup lang="ts">
import PageHeader from '../components/PageHeader.vue'
import AsyncState from '../components/AsyncState.vue'
import MetricCard from '../components/MetricCard.vue'
import { computed, onMounted, ref, watch } from 'vue'
import { useRouter } from 'vue-router'
import { Clock, InfoFilled, Refresh } from '@element-plus/icons-vue'
import { ElMessage, ElMessageBox, ElNotification } from 'element-plus'
import { api, apiErrorMessage, ensureCsrf } from '../services/api'
import type { AutoReplyPolicy, BrowserDevice, BrowserUnreadObservation, UnmatchedJobGroup } from '../types'

const router = useRouter(); const loading = ref(true); const switching = ref(false); const loadError = ref('')
const policies = ref<AutoReplyPolicy[]>([]); const devices = ref<BrowserDevice[]>([]); const observations = ref<BrowserUnreadObservation[]>([]); const groups = ref<UnmatchedJobGroup[]>([])
const startOpen = ref(false); const hours = ref(2); const tab = ref<'UNREAD'|'DONE'>('UNREAD'); const page = ref(1); const pageInput = ref(1); const selected = ref<BrowserUnreadObservation | null>(null); const jobId = ref('')
const active = computed(() => policies.value.filter(x => x.awayActive)); const watchable = computed(() => policies.value.filter(x => x.accountStatus === 'ACTIVE' && ['CONNECTED','DEGRADED'].includes(x.connectionStatus)))
const currentId = computed(() => observations.value.filter(x => x.unread && x.detailVerifiedAt).sort((a,b) => +new Date(b.detailVerifiedAt!) - +new Date(a.detailVerifiedAt!))[0]?.id)
const ordered = (items: BrowserUnreadObservation[]) => [...items].sort((a,b) => a.id === currentId.value ? -1 : b.id === currentId.value ? 1 : +new Date(b.latestMessageAt || b.lastSeenAt) - +new Date(a.latestMessageAt || a.lastSeenAt))
const unread = computed(() => ordered(observations.value.filter(x => x.unread && x.resolutionStatus === 'UNRESOLVED'))); const done = computed(() => ordered(observations.value.filter(x => !x.unread || x.resolutionStatus !== 'UNRESOLVED'))); const items = computed(() => tab.value === 'UNREAD' ? unread.value : done.value)
const pages = computed(() => Math.max(1, Math.ceil(items.value.length / 6))); const visible = computed(() => items.value.slice((page.value - 1) * 6, page.value * 6)); const online = computed(() => devices.value.filter(x => x.status === 'ACTIVE' && x.runtimeState === 'RUNNING').length); const drafts = computed(() => unread.value.filter(x => x.draftQualification === 'KNOWLEDGE_READY').length); const issues = computed(() => new Set(devices.value.filter(x => x.status === 'ACTIVE' && x.runtimeState !== 'RUNNING').map(x => x.accountId)).size)
const selectedGroup = computed(() => selected.value ? groups.value.find(x => x.observationIds.includes(selected.value!.id)) : undefined); const candidates = computed(() => selectedGroup.value?.candidates.filter(x => x.knowledgeReady) ?? [])
const labels: Record<BrowserUnreadObservation['eligibilityStatus'],string> = { OBSERVING:'观察中',AWAY_INACTIVE:'未挂机',SNAPSHOT_CONFIRMATION_REQUIRED:'等待确认',DETAIL_REQUIRED:'等待详情',READY_FOR_REVIEW:'待处理',HR_REPLIED:'HR 已回复',HR_HANDLED:'已处理',APPROVED_DRAFT:'草稿已审核',REJECTED:'已忽略',HUMAN_TAKEOVER:'人工接管' }
const fill: Record<BrowserUnreadObservation['fillStatus'],string> = { NONE:'尚未批准填入',READY:'待填入 BOSS',CLAIMED:'填入中',FILLED:'已填入未发送',UNKNOWN:'结果待人工确认' }

function showQueueHelp() {
  ElNotification({
    title: '消息队列说明',
    message: '消息队列仅展示岗位、账号与匿名定位码,不显示候选人姓名和消息正文。每页固定展示 6 条记录,支持页码跳转。',
    duration: 4000,
    type: 'info',
  })
}

function showTrendHelp() {
  ElNotification({
    title: '趋势图说明',
    message: '招聘活动趋势需要积累足够的历史记录数据后才会展示。当前系统正在收集中,请耐心等待。',
    duration: 4000,
    type: 'info',
  })
}

async function load(){ loading.value=true; loadError.value=''; try { const [p,d,o,g] = await Promise.all([api.get<AutoReplyPolicy[]>('/auto-replies/policies'),api.get<BrowserDevice[]>('/local-connector/devices'),api.get<BrowserUnreadObservation[]>('/local-connector/observations'),api.get<UnmatchedJobGroup[]>('/local-connector/observations/unmatched-job-groups')]); policies.value=p.data;devices.value=d.data;observations.value=o.data;groups.value=g.data } catch(e){loadError.value=apiErrorMessage(e,'值守状态加载失败')} finally{loading.value=false} }
function select(item:BrowserUnreadObservation){selected.value=item;jobId.value=''}; function move(value:number){page.value=Math.min(Math.max(1,value),pages.value);pageInput.value=page.value}; function age(value:string){const n=Math.max(0,Math.floor((Date.now()- +new Date(value))/60000));return n<60?`${n} 分钟`:n<1440?`${Math.floor(n/60)} 小时`:`${Math.floor(n/1440)} 天`}
function toggle(value:boolean|string|number){if(Boolean(value)){if(!watchable.value.length)return ElMessage.warning('请先连接至少一个招聘账号');startOpen.value=true}else void stop()}
async function start(){switching.value=true;try{await ensureCsrf();const endsAt=new Date(Date.now()+hours.value*3600000).toISOString();await Promise.all(watchable.value.map(x=>api.put(`/auto-replies/policies/${x.accountId}/away-mode`,{mode:hours.value>=12?'AFTER_HOURS':'TEMPORARY',endsAt})));startOpen.value=false;ElMessage.success('挂机值守已开启');await load()}catch(e){ElMessage.error(apiErrorMessage(e,'挂机值守开启失败'))}finally{switching.value=false}}
async function stop(){try{await ElMessageBox.confirm('确认结束全部招聘账号的挂机值守?','结束挂机');switching.value=true;await ensureCsrf();await Promise.all(active.value.map(x=>api.put(`/auto-replies/policies/${x.accountId}/away-mode`,{mode:'IN_OFFICE',endsAt:null})));await load()}catch(e){if(e!=='cancel'&&e!=='close')ElMessage.error(apiErrorMessage(e,'挂机值守结束失败'))}finally{switching.value=false}}
async function review(decision:'APPROVED'|'HUMAN_TAKEOVER'){if(!selected.value)return;try{let content:string|null=null,note='';if(decision==='APPROVED'){if(selected.value.draftQualification!=='KNOWLEDGE_READY')return ElMessage.warning('岗位回复资料尚未就绪');content=(await ElMessageBox.prompt('核对本次回复草稿','审核回复草稿',{inputValue:selected.value.reviewedContent||selected.value.draftContent||'',inputType:'textarea'})).value}else note=(await ElMessageBox.prompt('填写接管备注','人工接管')).value;await ensureCsrf();await api.put(`/local-connector/observations/${selected.value.id}/review`,{decision,content,note});selected.value=null;await load()}catch(e){if(e!=='cancel'&&e!=='close')ElMessage.error(apiErrorMessage(e,'会话处理失败'))}}
async function match(){const group=selectedGroup.value,job=candidates.value.find(x=>x.id===jobId.value);if(!group||!job)return ElMessage.warning('请选择一个已就绪的真实岗位');try{await ensureCsrf();await api.put('/local-connector/observations/manual-job-match',{observationIds:group.observationIds,jobPositionId:job.id,observedTitle:group.observedTitle,confirmedJobTitle:job.title,confirmed:true});selected.value=null;await load()}catch(e){ElMessage.error(apiErrorMessage(e,'岗位关联失败'))}}
watch([tab,items],()=>move(1));onMounted(load)
</script>
<template><div class="page-shell duty-page"><PageHeader><div><h1>今天的招聘值守</h1><p>挂机期间仅监测未读并生成安全草稿，发送仍由 HR 人工确认。<el-button :icon="InfoFilled" size="small" type="text" @click="showQueueHelp">查看说明</el-button></p></div><el-button :icon="Refresh" :loading="loading" @click="load">刷新</el-button></PageHeader><AsyncState v-if="loading" state="loading" :rows="8" aria-label="正在加载今日值守"/><AsyncState v-else-if="loadError" state="error" title="今日值守暂时无法加载" :message="loadError" @retry="load"><template #icon><el-icon><Refresh/></el-icon></template></AsyncState><template v-else><section class="overview"><article class="duty" :class="{active:active.length}"><el-icon><Clock/></el-icon><div><span>{{active.length?'挂机值守进行中':'当前在岗'}}</span><strong>挂机值守</strong><small>{{active.length?`${active.length} 个账号正在监测`:`${watchable.length} 个账号可用`}}</small></div><el-switch :model-value="!!active.length" :loading="switching" aria-label="挂机值守开关" @change="toggle"/></article><MetricCard label="桥接在线" :value="online" description="个账号可用" tone="teal"/><MetricCard label="当前未读" :value="unread.length" description="匿名会话待处理" tone="blue"/><MetricCard label="草稿就绪" :value="drafts" description="可人工审核" tone="amber"/></section><section id="attention-panel" class="workspace"><article id="message-queue" class="card-panel queue"><header><div><h2>消息队列</h2><p>仅展示岗位、账号与匿名定位码；每页 6 条。</p></div><div class="tabs"><button :class="{active:tab==='UNREAD'}" :aria-pressed="tab==='UNREAD'" @click="tab='UNREAD'">未读 {{unread.length}}</button><button :class="{active:tab==='DONE'}" :aria-pressed="tab==='DONE'" @click="tab='DONE'">最近处理</button></div></header><AsyncState v-if="!visible.length" state="empty" embedded :title="'当前没有' + (tab === 'UNREAD' ? '未读' : '已处理') + '消息'" message="新的会话状态产生后会在这里显示。"><template #icon><el-icon><Clock/></el-icon></template></AsyncState><div v-else class="message-list"><article v-for="item in visible" :key="item.id" class="card-entity" :class="{current:item.id===currentId}" tabindex="0" role="button" :aria-label="`查看 ${item.observedJobTitle || '待识别岗位'} 的消息`" @click="select(item)" @keydown.enter="select(item)" @keydown.space.prevent="select(item)"><b>{{(item.observedJobTitle||'待').slice(0,1)}}</b><div><strong>{{item.observedJobTitle||'岗位待识别'}}</strong><small>{{item.accountName}} · 定位码 {{item.anonymousKey}}<em v-if="item.id===currentId">当前浏览器会话</em></small></div><span><strong>{{item.unreadCount}}</strong><small>条未读</small></span><span><strong>{{age(item.firstSeenAt)}}</strong><small>持续时间</small></span><el-button @click.stop="select(item)">查看</el-button></article></div><footer><span>共 {{items.length}} 条</span><el-button :disabled="page===1" @click="move(page-1)">上一页</el-button><b>{{page}} / {{pages}}</b><el-button :disabled="page===pages" @click="move(page+1)">下一页</el-button><label>前往 <el-input-number v-model="pageInput" :min="1" :max="pages" controls-position="right" @change="move(Number(pageInput))"/> 页</label></footer></article><aside><article class="card-emphasis"><h2>今日优先事项</h2><p>{{issues?`${issues} 个账号连接需要检查`:'当前没有账号异常'}}</p><el-button link type="primary" @click="router.push('/boss-accounts')">检查账号</el-button></article><article class="card-panel trend"><h2>招聘活动趋势</h2><div><el-icon><Clock/></el-icon><strong>暂未积累足够数据</strong><small>形成连续历史记录后再展示趋势。<el-button :icon="InfoFilled" size="small" type="text" @click="showTrendHelp">查看说明</el-button></small></div></article></aside></section></template><el-dialog append-to-body v-model="startOpen" title="开启挂机值守" width="440px"><el-radio-group v-model="hours"><el-radio-button :value="2">2 小时</el-radio-button><el-radio-button :value="4">4 小时</el-radio-button><el-radio-button :value="12">到明早</el-radio-button></el-radio-group><template #footer><el-button @click="startOpen=false">取消</el-button><el-button type="primary" :loading="switching" @click="start">开始挂机</el-button></template></el-dialog><el-dialog append-to-body :model-value="!!selected" title="未读消息" width="620px" @close="selected=null"><template v-if="selected"><h3>{{selected.observedJobTitle||'岗位待识别'}}</h3><p class="meta">{{selected.accountName}} · 匿名会话 {{selected.anonymousKey}}</p><p>状态：{{labels[selected.eligibilityStatus]}} · {{selected.unreadCount}} 条未读 · {{age(selected.firstSeenAt)}}</p><section v-if="selectedGroup" class="match"><strong>关联真实岗位</strong><small>选择同账号已就绪岗位</small><el-select v-model="jobId" placeholder="选择同账号已就绪岗位"><el-option v-for="job in candidates" :key="job.id" :label="job.title" :value="job.id"/></el-select><el-button type="primary" :disabled="!jobId" @click="match">确认关联</el-button></section><section v-if="selected.draftContent" class="draft"><header>回复草稿 <el-tag v-if="selected.reviewStatus==='APPROVED'">{{fill[selected.fillStatus]}}</el-tag></header><p>{{selected.reviewedContent||selected.draftContent}}</p><small v-if="selected.fillStatus==='FILLED'">已填入未发送，需人工确认。</small></section></template><template #footer><el-button @click="selected=null">关闭</el-button><el-button v-if="selected?.eligibilityStatus==='READY_FOR_REVIEW'" @click="review('HUMAN_TAKEOVER')">人工接管</el-button><el-button v-if="selected?.eligibilityStatus==='READY_FOR_REVIEW'" type="primary" @click="review('APPROVED')">审核草稿</el-button></template></el-dialog></div></template>
<style scoped>
.duty-page { max-width:1480px; }
.overview { display:grid; grid-template-columns:1.4fr repeat(3,minmax(0,1fr)); gap:16px; margin-bottom:24px; }
.duty { display:flex; align-items:center; gap:16px; padding:22px; border:1px solid var(--border-teal); border-radius:16px; background:linear-gradient(145deg,var(--surface-teal),var(--surface)); }
.duty > .el-icon { display:grid; place-items:center; width:42px; height:42px; flex:0 0 auto; border-radius:12px; background:var(--brand-50); color:var(--primary); font-size:23px; }
.duty > div { flex:1; min-width:0; }.duty div > * { display:block; }.duty strong { margin:7px 0; font-size:22px; }.duty span,.duty small { font-size:12px; color:var(--text-secondary); }
.duty.active { background:var(--primary); border-color:var(--primary); color:white; }.duty.active span,.duty.active small { color:#d9fffa; }.duty.active > .el-icon { background:rgba(255,255,255,.15); color:white; }
.overview .card-indicator { --metric-value-size:32px; display:flex; flex-direction:column; justify-content:center; padding:22px; }.overview .card-indicator:nth-child(2) { --indicator-surface:var(--surface-teal); --indicator-border:var(--border-teal); }.overview .card-indicator:nth-child(3) { --indicator-surface:var(--surface-blue); --indicator-border:var(--border-blue); }.overview .card-indicator:nth-child(4) { --indicator-surface:var(--surface-amber); --indicator-border:var(--border-amber); }
.workspace { display:grid; grid-template-columns:minmax(0,2.2fr) minmax(260px,1fr); gap:18px; align-items:stretch; }
.queue { display:flex; flex-direction:column; overflow:hidden; padding:0; }
.queue > header { display:flex; align-items:center; justify-content:space-between; gap:16px; padding:20px 22px; border-bottom:1px solid var(--border); }
h2 { margin:0; font-size:17px; }.queue p,.meta { font-size:12px; color:var(--text-secondary); margin:6px 0 0; line-height:1.6; }
.tabs { display:flex; flex-shrink:0; gap:3px; padding:4px; background:var(--surface-soft); border-radius:9px; }
.tabs button { padding:8px 11px; background:transparent; border:0; border-radius:6px; color:var(--text-secondary); cursor:pointer; font-size:12px; }.tabs button.active { background:white; color:var(--primary); box-shadow:var(--shadow-rest); font-weight:600; }
.message-list { flex:1; }.message-list article { display:grid; grid-template-columns:34px minmax(0,1fr) 54px 72px auto; align-items:center; gap:12px; padding:16px 22px; border:0; border-bottom:1px solid var(--border-subtle); border-radius:0; box-shadow:none; }
.message-list article:hover { transform:none; background:var(--surface-soft); box-shadow:none; }.message-list article.current { background:var(--brand-50); box-shadow:inset 3px 0 var(--primary); }
.message-list b { display:grid; place-items:center; width:34px; height:34px; border-radius:10px; background:var(--brand-50); color:var(--primary); }
.message-list article > div { min-width:0; }.message-list strong,.message-list small { display:block; }.message-list strong { font-size:13px; line-height:1.5; }.message-list article > div > strong { display:-webkit-box; -webkit-box-orient:vertical; -webkit-line-clamp:2; overflow:hidden; }
.message-list small { margin-top:4px; color:var(--text-secondary); font-size:11px; overflow-wrap:anywhere; }.message-list em { display:block; font-style:normal; color:var(--primary); }
.queue > footer { display:flex; align-items:center; justify-content:flex-end; flex-wrap:wrap; gap:8px; padding:16px 22px; border-top:1px solid var(--border); font-size:12px; }
.queue > footer > span { margin-right:auto; color:var(--text-secondary); }.queue label { display:flex; align-items:center; gap:6px; }.queue :deep(.el-input-number) { width:76px; }.queue footer .el-button { margin:0; }
.workspace > aside { display:flex; flex-direction:column; gap:16px; min-width:0; }
.card-emphasis { padding:22px; }.card-emphasis p { margin:10px 0 12px; color:var(--text-secondary); font-size:13px; line-height:1.6; }
.trend { flex:1; display:flex; flex-direction:column; min-height:260px; padding:0; border-color:var(--border-blue); background:linear-gradient(155deg,var(--surface) 45%,var(--surface-blue)); }
.trend > h2 { padding:20px 22px; border-bottom:1px solid var(--border-subtle); }
.trend > div { display:flex; flex-direction:column; flex:1; justify-content:center; align-items:center; padding:28px 22px; gap:12px; text-align:center; }
.trend > div > .el-icon { width:48px; height:48px; border-radius:12px; background:#e3eefb; color:var(--color-info); font-size:24px; }.trend small { font-size:12px; color:var(--text-secondary); line-height:1.6; }
.match,.draft { display:grid; gap:12px; margin-top:20px; padding:16px; border-radius:10px; background:var(--surface-soft); }.draft header { display:flex; align-items:center; justify-content:space-between; gap:12px; }.draft p { white-space:pre-wrap; line-height:1.7; margin:0; }.match small,.draft small { color:var(--text-secondary); }
@media(max-width:1180px) { .workspace { grid-template-columns:1fr; }.workspace > aside { display:grid; grid-template-columns:1fr 1fr; }.overview { grid-template-columns:repeat(2,minmax(0,1fr)); } }
@media(max-width:600px) { .overview { gap:10px; }.duty { grid-column:1/-1; padding:18px; }.overview .card-indicator { padding:16px; }.overview .card-indicator:last-child { grid-column:1/-1; }.workspace > aside { display:flex; }.queue > header { align-items:stretch; flex-direction:column; padding:18px; }.tabs button { flex:1; }.message-list article { grid-template-columns:34px minmax(0,1fr) auto; gap:10px; padding:16px; }.message-list article > div { grid-column:2/4; }.message-list article > span { grid-row:2; }.message-list article > span:nth-of-type(1) { grid-column:1/3; display:flex; align-items:center; gap:6px; }.message-list article > span:nth-of-type(2) { grid-column:1/3; grid-row:3; display:flex; gap:6px; align-items:center; }.message-list article > .el-button { grid-column:3; grid-row:2/4; }.message-list article > span small { margin:0; }.queue > footer { padding:16px; }.queue > footer > span { flex-basis:100%; } }
</style>
